direct_event = '''                SwarmEvent::Behaviour(BehaviourEvent::DirectChat(event)) => {\n                    match event {\n                        request_response::Event::Message { peer, message, .. } => {\n                            match message {\n                                request_response::Message::Request { request, channel, .. } => {\n                                    let response = match request {\n                                        DirectChatRequest::Chat(message) => {\n                                            let peer_text = peer.to_string();\n                                            let known_nick_matches = peers\n                                                .get(&peer)\n                                                .is_some_and(|presence| presence.nick == message.nick);\n                                            let valid = message.peer_id.as_deref() == Some(peer_text.as_str())\n                                                && known_nick_matches\n                                                && wire_event_is_well_formed(&WireEvent::Chat(message.clone()));\n                                            if valid {\n                                                let _ = app.emit("chat-message", message);\n                                                DirectChatResponse::Ack\n                                            } else {\n                                                DirectChatResponse::Rejected {\n                                                    reason: "Direct chat identity or payload validation failed.".into(),\n                                                }\n                                            }\n                                        }\n                                    };\n                                    let _ = swarm.behaviour_mut().direct_chat.send_response(channel, response);\n                                }\n                                request_response::Message::Response { .. } => {}\n                            }\n                        }\n                        request_response::Event::OutboundFailure { peer, error, .. } => {\n                            let _ = app.emit("network-log", format!("Direct chat fallback to {peer} failed: {error}"));\n                        }\n                        request_response::Event::InboundFailure { peer, error, .. } => {\n                            let _ = app.emit("network-warning", format!("Direct chat fallback from {peer} failed: {error}"));\n                        }\n                        request_response::Event::ResponseSent { .. } => {}\n                    }\n                }\n                SwarmEvent::Behaviour(BehaviourEvent::FileTransfer(event)) => {'''
text = replace_once(text, file_event_marker, direct_event, "direct chat event loop")

LIB.write_text(text, encoding="utf-8")

